#!/usr/bin/env bash
# Fetch the Cesium skill for AI models into agent-plugin/skills/cesium-language/:
# SKILL.md and the pages it refers to (references/), as the website publishes
# them (generated from the specification by cesium-site-ai of
# cesiumlang/cesiumlang.org; cesiumlang/cesiumlang.org#25). The agent plugin
# and the extension (contributes.chatSkills) ship this copy. It is
# regenerated by this script, never edited.
#
# usage: bash tools/fetch-skill.sh [HOST]   (default: cesiumlang.org; cesiumlang.dev for the development site)
set -euo pipefail
ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
host=${1:-cesiumlang.org}
base=https://$host/skill/cesium-language
dir=$ROOT/agent-plugin/skills/cesium-language

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
curl -fsSL --retry 3 -o "$work/SKILL.md" "$base/SKILL.md"
head -n 1 "$work/SKILL.md" | grep -qx -- '---' || { echo "$base/SKILL.md is not a skill" >&2; exit 1; }
# every page the skill links to
for ref in $(grep -o 'references/[A-Za-z0-9_./-]*\.md' "$work/SKILL.md" | sort -u); do
  mkdir -p "$(dirname "$work/$ref")"
  curl -fsSL --retry 3 -o "$work/$ref" "$base/$ref"
done

rm -rf "$dir"
mkdir -p "$(dirname "$dir")"
mv "$work" "$dir"
trap - EXIT
printf 'Fetched from %s on %s by tools/fetch-skill.sh: regenerated, never edited.\n' "$base/" "$(date -u +%Y-%m-%d)" > "$dir/source.txt"
echo "$(find "$dir" -name '*.md' | wc -l | tr -d ' ') files from $base"
